INSERT INTO pages (link, image, status) VALUES ('ilk-dis-muayenesi-tedavi-planlamasi', '', 1);

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'İlk Diş Muayenesi ve Kapsamlı Tedavi Planlaması',
'<p>Kapsamlı ilk muayene; şikâyetin dinlenmesi, tıbbi ve dental öykü, ağız ile çevre dokuların klinik değerlendirilmesi ve yalnız gerekli görülen kayıtların birlikte yorumlanmasıdır. Tedavi planı bu bulgular, hastanın öncelikleri ve uygun seçenekler üzerinden aşamalı olarak oluşturulur.</p>
<p><img src="/assets/uploads/images/ts18-ilk-dis-muayenesi-gorusme.webp" alt="İlk muayenede hastanın başvuru nedeninin ve beklentilerinin dinlenmesi" loading="lazy" /></p>
<h2>Başvuru nedeni ve beklentiler</h2>
<p>Ağrı, estetik beklenti, çiğneme güçlüğü, eksik diş, mevcut restorasyonlar ve öncelikler hastanın kendi anlatımıyla kaydedilir. İlk amaç yalnız bir işlem seçmek değil; ihtiyaçları ve karar ölçütlerini anlamaktır.</p>
<h2>Tıbbi ve dental öykü</h2>
<p>Sistemik hastalıklar, alerjiler, gebelik olasılığı, önceki ameliyat ve tedaviler, kullanılan ilaçlar ile geçmiş dental deneyimler sorgulanır. Gerekli olduğunda hastanın takip eden hekiminin görüşü alınır; hasta ilaçlarını kendi kararıyla bırakmaz. Gebelikte tedavi planlaması için <a href="/hamilelikte-dis-tedavisi/">Hamilelikte Diş Tedavisi</a> sayfasına bakabilirsiniz.</p>
<h2>Ağız dışı ve yumuşak doku muayenesi</h2>
<p>Yüz simetrisi, çene hareketleri, lenf düğümleri ve gerekli ağız dışı bulgular; dudak, yanak, dil, damak ve ağız tabanı gibi yumuşak dokular sistematik biçimde değerlendirilir. Şüpheli bir bulgu saptanırsa ileri değerlendirme ve gerekli testler planlanır.</p>
<h2>Dişler ve mevcut restorasyonlar</h2>
<p><a href="/dis-curugu-kompozit-dolgu/">Çürük</a> şüphesi, kırık ve aşınmalar, renk değişiklikleri, hassasiyet, diş hareketliliği, dolgu-kuron-köprülerin durumu ve eksik diş alanları klinik bulgularla değerlendirilir. Gerekirse canlılık ve diğer yardımcı testler eklenir.</p>
<p><img src="/assets/uploads/images/ts18-kapsamli-agiz-dis-muayenesi.webp" alt="Dişlerin, diş etinin ve ağız dokularının sistematik muayenesi" loading="lazy" /></p>
<h2>Diş eti ve periodontal değerlendirme</h2>
<p>Plak ve diş taşı, kanama, diş eti çekilmesi, cep derinliği, destek dokular ve risk göstergeleri değerlendirilir. Diş eti sağlığı; implant, protetik veya estetik işlemlerden önce tedavi sırasını değiştirebilir.</p>
<h2>Muayene verileri birlikte nasıl kullanılır?</h2>
<table>
<thead><tr><th>Kayıt</th><th>Katkısı</th><th>Kullanım ilkesi</th></tr></thead>
<tbody>
<tr><td>Klinik muayene</td><td>Diş, diş eti, yumuşak doku, çene eklemi ve kapanış bulguları</td><td>Her hastada kapsamı ihtiyaca göre belirlenen temel değerlendirme</td></tr>
<tr><td>Radyografik kayıt</td><td>Gözle görülemeyen kök, kemik ve ara yüzlerin değerlendirilmesi</td><td>Yalnız öykü, önceki kayıtlar ve klinik bulguya göre gerekli görüntü</td></tr>
<tr><td>Fotoğraf / dijital tarama</td><td>Başlangıç durumunu, diş dizisini ve kapanışı belgelemeye yardımcı kayıt</td><td>Tedavi türü ve planlama ihtiyacına göre; tek başına kesin tanı değildir</td></tr>
</tbody>
</table>
<p><strong>Önemli:</strong> Panoramik film, tomografi, fotoğraf veya dijital tarama her hastada otomatik bir paket değildir. Önceki kayıtların tarihi ve tanısal yeterliliği değerlendirilir; yeni kayıt yalnız klinik gereklilik varsa alınır.</p>
<p><img src="/assets/uploads/images/ts18-klinik-radyografik-dijital-degerlendirme.webp" alt="Klinik, radyografik ve dijital kayıtların birlikte değerlendirilmesi" loading="lazy" /></p>
<h2>Kapanış, eklem ve fonksiyon</h2>
<p>Diş temasları, çiğneme ilişkisi, ağız açıklığı, eklem ve kas yakınmaları, sıkma-gıcırdatma ile aşınma bulguları değerlendirilir. Her ses veya aşınma tek başına hastalık ya da plak gerekliliği anlamına gelmez.</p>
<h2>Görüntüleme seçimi</h2>
<p>Bite-wing, periapikal, panoramik veya üç boyutlu görüntüleme; muayene bulgusu ve planlanan işleme göre seçilir. Her hastaya tomografi yaklaşımı kullanılmaz; beklenen tanısal katkı ile radyasyon maruziyeti birlikte değerlendirilir.</p>
<h2>Dijital kayıtların rolü</h2>
<p>Ağız içi tarayıcıyla alınan kayıtlar, standart fotoğraflar ve dijital modeller; başlangıç durumunu, kapanışı ve restoratif planı belgelemeye yardımcı olabilir. Yazılım çıktısı, hekim muayenesinin ve klinik doğrulamanın yerine geçmez.</p>
<h2>Tanı ve risk değerlendirmesi</h2>
<p>Çürük, diş eti hastalığı, pulpa ve kök ucu sorunları, kırık riski, hijyen, sigara, beslenme ve bakım alışkanlıkları birlikte ele alınır. Kesinleştirilemeyen bulgular için izlem veya ek test planlanabilir.</p>
<h2>Aşamalı tedavi planı</h2>
<ol>
<li>Acil ağrı ve enfeksiyonun kontrolü</li>
<li>Hastalığın durdurulması ve temel diş eti sağlığı</li>
<li>Kesin restoratif, cerrahi veya protetik aşamalar</li>
<li>Bakım ve kişiye göre belirlenen kontrol aralığı</li>
</ol>
<p>Klinik durum bu sıralamayı değiştirebilir. Planın hangi başlıkları içerdiği ve nasıl güncellendiği için <a href="/tedavi-plani-ve-surec/">Tedavi Planı ve Süreç</a> sayfasına bakabilirsiniz.</p>
<p><img src="/assets/uploads/images/ts18-asamali-tedavi-plani-ve-bilgilendirme.webp" alt="Aşamalı tedavi planının hastaya anlatılması" loading="lazy" /></p>
<h2>Seçenekler ve süreç</h2>
<p>Her uygulanabilir seçeneğin amacı, önemli yarar ve riskleri, alternatifleri, tedavisiz kalmanın olası sonuçları ile tahmini süre ve kapsam anlaşılır biçimde konuşulur. Plan, yeni klinik bulgulara veya iyileşme yanıtına göre güncellenebilir. Aydınlatılmış onam yalnız bir imza değil; anlaşılır bilgilendirme ve soru sorma sürecidir.</p>
<h2>Sık sorulan sorular</h2>
<p><strong>İlk muayenede hemen tedavi yapılır mı?</strong><br>Her zaman değil. Öncelik değerlendirme ve güvenli planlamadır. Acil ağrı veya uygun basit bir işlem; zaman ve onam varsa aynı gün ele alınabilir. Kapsamlı tedavi çoğunlukla planlama sonrası başlar.</p>
<p><strong>Her hastadan panoramik röntgen istenir mi?</strong><br>Hayır. Görüntüleme türü ve zamanı; öykü, klinik muayene, önceki filmler ve planlanan işleme göre belirlenir. Mevcut kayıtlar yeterliyse gereksiz tekrar yapılmaz.</p>
<p><strong>Tedavi planında öncelik nasıl belirlenir?</strong><br>Acil durum ve enfeksiyon kontrolü önce gelir; diş eti ve çürük kontrolü gibi temel aşamalar tamamlandıktan sonra kesin restorasyon, implant-protez veya estetik işlemler planlanır.</p>
<p><strong>İkinci görüş için mevcut kayıtlarımı getirebilir miyim?</strong><br>Evet. Radyografiler, raporlar, implant bilgileri ve önceki tedavi kayıtları değerlendirmeye yardımcı olabilir. Ancak güncellik veya görüntü kalitesi yetersizse ek kayıt gerekebilir.</p>
<h2>Yerel değerlendirme</h2>
<p>Beylikdüzü/Esenyurt bağlantısındaki kliniğimizde ilk muayene; şikâyet, tıbbi öykü, diş ve diş eti sağlığı, kapanış ile yalnız gerekli klinik ve dijital kayıtların birlikte değerlendirildiği kapsamlı bir planlama süreci olarak ele alınır.</p>
